 void RouteLine(Vector2 a,Vector2 b,Color color,bool dashed=false){var old=GUI.matrix;Color oc=GUI.color;Vector2 v=b-a;GUIUtility.RotateAroundPivot(Mathf.Atan2(v.y,v.x)*Mathf.Rad2Deg,a);GUI.color=color;if(dashed){for(float x=0;x<v.magnitude;x+=13)GUI.DrawTexture(new Rect(a.x+x,a.y,Mathf.Min(7,v.magnitude-x),2),white);}else GUI.DrawTexture(new Rect(a.x,a.y,v.magnitude,2),white);GUI.color=oc;GUI.matrix=old;}
 Vector2 TrailPosition(TrailNode n){return new Vector2(125+n.row*205,n.row==4?405:285+n.lane*160+(n.row%2)*24);}
 string NodeGlyph(string kind){switch(kind.ToLowerInvariant()){case "battle":return "X";case "elite":return "!!";case "boss":return "III";case "shop":case "armory":return "+";case "camp":return "^";default:return "?";}}
 void CampaignMap(){bool trail=campaign.mode=="trail";var texture=trail?trailMap:worldMap;if(texture)GUI.DrawTexture(new Rect(0,100,1055,715),texture,ScaleMode.ScaleAndCrop);Rect(0,100,1055,715,new Color(.02f,.04f,.045f,.12f));Frame(1060,120,510,690);Banner((trail?"TRAIL OF DEATH":"CONQUEST")+"  /  "+data.F(campaign.faction).name+"  ·  Gold "+campaign.gold+"  ·  "+(trail?"Act "+campaign.act+" / 3":"Turn "+campaign.turn));
  Frame(35,126,980,68,new Color(.035f,.07f,.08f,.9f));Text(trail?"THE ASHEN PILGRIMAGE":"THE RELAY FRONTIER",55,136,940,30,heading);Text(trail?"Choose a glowing connected encounter. The expedition cannot turn back.":"Select a settlement. Lines show adjacent regions your army can reach.",55,171,940,25,small);
  if(trail){var nodes=campaign.nodes.Where(n=>n.act==campaign.act).ToList();foreach(var a in nodes)foreach(var b in nodes.Where(b=>b.row==a.row+1&&(b.row==4||Math.Abs(a.lane-b.lane)<=1)))RouteLine(TrailPosition(a),TrailPosition(b),new Color(.86f,.94f,.91f,.6f),true);foreach(var n in nodes){Vector2 pos=TrailPosition(n);bool available=campaign.Available(n);Color c=available?new Color(.4f,.91f,.83f):n.visited?gold:new Color(.22f,.31f,.34f);Frame(pos.x-29,pos.y-29,58,58,c*.6f);bool old=GUI.enabled;GUI.enabled=old&&available;if(GUI.Button(new Rect(pos.x-25,pos.y-25,50,50),n.visited?"✓":NodeGlyph(n.kind),available?selectedButton:button)){campaign.Visit(n);Save();}GUI.enabled=old;Frame(pos.x-67,pos.y+36,134,27,new Color(.02f,.05f,.06f,.88f));Text(n.kind.ToUpperInvariant(),pos.x-65,pos.y+37,130,25,new GUIStyle(small){alignment=TextAnchor.MiddleCenter});}Frame(55,733,920,52,new Color(.025f,.055f,.065f,.91f));Text("X  Battle     !!  Elite     III  Boss     +  Armory     ^  Camp     ?  Event",75,748,880,27,body);}
  else{foreach(var r in campaign.provinces){Vector2 a=RegionPosition(r.x,r.y);foreach(var other in campaign.provinces.Where(o=>o.id>r.id&&Math.Abs(o.x-r.x)+Math.Abs(o.y-r.y)==1))RouteLine(a,RegionPosition(other.x,other.y),new Color(.86f,.87f,.72f,.5f),true);}foreach(var r in campaign.provinces){var pos=RegionPosition(r.x,r.y);Color c=r.owner==""?new Color(.45f,.47f,.42f):BattleVisuals.ColorOf(data.F(r.owner).color);Frame(pos.x-99,pos.y-33,198,69,Color.Lerp(new Color(.035f,.06f,.07f,.96f),c,.23f));Rect(pos.x-99,pos.y-33,4,69,c);string owner=r.owner==""?(r.ruined>0?"SCORCHED":"UNCLAIMED"):data.F(r.owner).name;int armyCount=campaign.armies.Count(a=>a.region==r.id);if(Btn(r.name+"  ·  T"+r.tier+(armyCount>0?"  ["+armyCount+"]":""),pos.x-94,pos.y-30,188,34,campaign.selectedProvince==r.id))campaign.selectedProvince=r.id;Text(owner,pos.x-91,pos.y+10,182,26,new GUIStyle(small){fontSize=12,alignment=TextAnchor.MiddleCenter});}ConquestOrders();}CampaignArmy();}
